export const metadata: Metadata = { title: 'The stats engine', description: 'Every Rallymetrica statistic defined: what each metric needs (Score, Counter or Detailed), how it is counted, how momentum, aggression, pressure, patterns and practice sessions are computed, and how matches become a trend.' }

type Level = 'Score' | 'Counter' | 'Detailed' | 'Session'
type Row = { metric: string; how: string; needs: Level; better?: 'up' | 'down' }
type Group = { id: string; title: string; page: string; lead: string; rows: Row[]; notes?: string[]; theory?: string[]; reading?: string[]; sample?: { n: string; why: string } }

const levels: { name: Level; what: string; unlocks: string }[] = [
  { name: 'Score', what: 'You tap the side that won the point. The engine keeps the score, the games and sets under the match’s rules, every break point and pressure situation, and the momentum curve.', unlocks: 'Points won · break points · the whole Pressure page · Momentum · Timeline' },
  { name: 'Counter', what: 'You tap once per shot and record how the point ended — ace, service winner, winner, forced or unforced error, double fault — and the wing. Everything about serving, returning and endings follows.', unlocks: 'Serve · Return · winners and errors · rally length · Aggression' },
  { name: 'Detailed', what: 'You tap where each ball landed. That adds the geometry: direction and depth, serve targets, zone traits, the landing maps, the full rally replay and pattern matching.', unlocks: 'Placement · Landings · serve zones · Patterns · replay paths' },
]

const groups: Group[] = [
  { id: 'points', title: 'Points and serve', page: 'POINTS · SERVE', lead: 'The headline rows: the result, the serve, and how points ended.', rows: [
    { metric: 'Points won', how: 'points won ÷ points played', needs: 'Score', better: 'up' },
    { metric: 'Break points won', how: 'break points converted ÷ break points held as the receiver', needs: 'Score', better: 'up' },
    { metric: 'Win rate (Stats only)', how: 'matches won ÷ matches in the window — one dot per match, drawn as the running rate; no cut applies', needs: 'Score', better: 'up' },
    { metric: '1st serve in', how: 'first serves in ÷ service points', needs: 'Counter', better: 'up' },
    { metric: '1st serve pts won', how: 'points won behind a first serve ÷ first serves in', needs: 'Counter', better: 'up' },
    { metric: '2nd serve in', how: 'second serves in ÷ second-serve points (a double fault counts against)', needs: 'Counter', better: 'up' },
    { metric: '2nd serve pts won', how: 'points won behind a second serve ÷ second-serve points (a double fault is a second-serve point lost)', needs: 'Counter', better: 'up' },
    { metric: 'Aces', how: 'serves the receiver did not touch', needs: 'Counter', better: 'up' },
    { metric: 'Service winners', how: 'serves touched but not put back in play', needs: 'Counter', better: 'up' },
    { metric: 'Double faults', how: 'second serves missed (on a one-serve rally session the row reads Faults: the one serve missed)', needs: 'Counter', better: 'down' },
    { metric: 'Winners', how: 'shots that ended the point without the opponent reaching the ball', needs: 'Counter', better: 'up' },
    { metric: 'Unforced errors', how: 'errors recorded as unforced', needs: 'Counter', better: 'down' },
    { metric: 'Forced errors', how: 'errors recorded as forced by the opponent’s shot', needs: 'Counter', better: 'down' },
    { metric: 'Total errors', how: 'unforced + forced', needs: 'Counter', better: 'down' },
  ], reading: [
    'Read the table in pairs, not rows. **Points won against break points won**: 52% of points with 20% of break points is not a tennis problem but a pressure one — the Pressure page will confirm it. **Winners against unforced errors**: more winners than unforced is a match played on your terms; the reverse means the opponent only had to keep the ball in. **Forced against unforced errors**: forced errors you committed are the opponent’s good play, unforced are yours — twice as many forced as unforced is a player who was beaten; the reverse is a player who beat themselves.',
    'The serve rows are a chain, top to bottom. **1st serve in** high with **1st serve pts won** low is a serve that goes in but goes nowhere — look at the zones. 1st serve in low with 1st serve pts won high is a weapon that misses too often: a percentage problem, not a serve problem. **2nd serve pts won** under 40% with double faults present is the second serve, and it is the row most matches are decided on — below 50% the server is losing their own second-serve points. **Aces** and **service winners** are the free points; both near zero against a weak returner says the serve starts the point and nothing more.',
    'Trust the fraction, not the percentage: 67% of three points is noise, 67% of thirty is a fact. The report prints n/d under every ratio for this reason.',
  ], sample: { n: '20 points under a cut', why: 'a serve or return percentage over fewer than twenty points moves ten points with two results; compare cuts across a season on Stats before changing anything' } },
  { id: 'return', title: 'Return', page: 'RETURN', lead: 'The same facts read from the receiver’s side.', rows: [
    { metric: '1st serve return in', how: 'returns put in play ÷ first-serve points received', needs: 'Counter', better: 'up' },
    { metric: '1st serve return pts won', how: 'points won when receiving a first serve ÷ first-serve points received', needs: 'Counter', better: 'up' },
    { metric: '2nd serve return in', how: 'returns put in play ÷ second serves received that landed', needs: 'Counter', better: 'up' },
    { metric: '2nd serve return pts won', how: 'points won when receiving a second serve ÷ second-serve points received (a double fault is one won)', needs: 'Counter', better: 'up' },
    { metric: 'Return winners', how: 'returns that won the point outright', needs: 'Counter', better: 'up' },
    { metric: 'Return errors', how: 'returns missed — unforced, forced and total', needs: 'Counter', better: 'down' },
  ], reading: [
    'Return is the serve chain read from the other side, and the two pages should agree: the server’s 2nd serve pts won and the receiver’s 2nd serve return pts won sum to 100% of the same points.',
    '**1st serve return in** low is position and reaction — the returner is standing where the first serve beats them. **2nd serve return in** low is intent: a second-serve return that keeps missing was being attacked too hard; the fix is the target, not the swing. **2nd serve return pts won** is the single best measure of whether the opponent’s weakness was punished — under 50% against a player with double faults on the Serve page is a chance left on the court.',
    '**Return winners** against **return errors**: a returner with many of both is going for it; few of both is a returner who puts the ball back and lets the rally decide — right against a big server, wrong against a weak second serve. Read it under the **Deuce · Ad** track on a Detailed match: most players return from one side far better than the other, and the whole-page figure hides it.',
  ] },
  { id: 'pressure', title: 'Pressure', page: 'PRESSURE', lead: 'Twelve rows, every one read from the score before the point. Only Score tracking is needed for all of them.', rows: [
    { metric: 'Pressure points won', how: 'points won ÷ pressure points — a break point for either side, 40–40 and after, or any tiebreak point', needs: 'Score', better: 'up' },
    { metric: 'Break points won', how: 'converted ÷ held, as the receiver', needs: 'Score', better: 'up' },
    { metric: 'Break points saved', how: 'saved ÷ faced, as the server', needs: 'Score', better: 'up' },
    { metric: 'First points won', how: 'the first point of each game', needs: 'Score', better: 'up' },
    { metric: '30–30 points won', how: 'points played from 30–30', needs: 'Score', better: 'up' },
    { metric: '40–40 points won', how: 'points played from deuce', needs: 'Score', better: 'up' },
    { metric: 'Breaks consolidated', how: 'service games held straight after breaking, of such games (same set)', needs: 'Score', better: 'up' },
    { metric: 'Breaks back', how: 'games broken straight back after being broken, of such games', needs: 'Score', better: 'up' },
    { metric: 'Set points won', how: 'set points converted ÷ set points held', needs: 'Score', better: 'up' },
    { metric: 'Set points saved', how: 'set points saved ÷ set points faced', needs: 'Score', better: 'up' },
    { metric: 'Match points saved', how: 'match points saved ÷ match points faced', needs: 'Score', better: 'up' },
    { metric: 'Tiebreak points won', how: 'points won in tiebreaks ÷ tiebreak points played', needs: 'Score', better: 'up' },
  ], notes: ['A set point or match point is decided before the point is played: winning it would end the set or the match, for either side, under the match’s rules. The engine replays the scoring rules to know.', 'Game-level rows (breaks consolidated, breaks back) read whole games, so a set filter applies to them and a score filter does not.', 'Pressure is a match page. A rally session has a tally, not a tennis score, so it has no pressure rows, no situation cut and no score cut.'], reading: [
    'Read every pressure row against the **Points won** row above it: the gap is the finding. **Pressure points won** ten points below Points won is a player who tightens; ten above is one who waits for the big points and coasts the rest — both are coaching conversations, different ones.',
    '**Break points won** (as receiver) against **break points saved** (as server): few converted and many saved is a server who plays the big point well and a returner who does not; the reverse is a player who attacks under pressure and defends poorly under it. **First points won** says how games start, **30–30** and **40–40** how they are decided — a player at 60% of first points and 35% at 30–30 starts well and gives it back.',
    '**Breaks consolidated** is the row coaches watch most: a break not followed by a hold was a break given straight back, and a low figure here beside a healthy break-point row means the match was lost in the game after the good news. **Breaks back** is its mirror — high is resilience, low is a player who goes away once broken.',
    'The closing rows: **set points won** low with **set points saved** high says the sets were long and tight, not that the player cannot close; **match points saved** above zero is a match that was nearly lost before it was won — or the reverse. **Tiebreak points won** below Points won is a player who plays tiebreaks worse than games; practise them as a format, not a stroke.',
  ], sample: { n: '6 break points', why: 'break-point rows swing 17 points with one result below six; read them across a window of matches on Stats, where ten matches carry forty or more' } },
  { id: 'placement', title: 'Placement', page: 'PLACEMENT · LANDINGS', lead: 'Where the balls went. Every row here needs the landings a Detailed match records.', rows: [
    { metric: 'Crosscourt · Down the line · Middle', how: 'share of the player’s shots by direction', needs: 'Detailed' },
    { metric: 'Deep landings', how: 'landings beyond the player’s deep line ÷ landings in court', needs: 'Detailed', better: 'up' },
    { metric: 'Serves T · middle · wide', how: 'share of serves in, by target', needs: 'Detailed' },
    { metric: '1st serves here · 2nd serves here', how: 'serves in under the lit serve zone — DEUCE · AD, T · MID · WIDE', needs: 'Detailed', better: 'up' },
    { metric: 'Forehands from own FH zone', how: 'balls arriving in the forehand zone taken with a forehand ÷ balls arriving there', needs: 'Detailed', better: 'up' },
    { metric: 'Into opponent’s FH zone', how: 'share of shots sent into the opponent’s forehand zone', needs: 'Detailed', better: 'down' },
  ], notes: ['Where “deep”, “middle” and the forehand zone begin is set per player — the zone traits under Players → profile → Zones (Middle 10–75, Deep 50–90, FH 50–100, T · wide 5–25). A change made at match setup applies to that match only. The serve court and a serve session’s placement map draw the same T and wide zones from the server’s traits.', 'A serve has no origin, so serve placement reads T · middle · wide only: no direction or depth rows, and no forehand-zone row — which wing a serve found depends on the service box and is never inferred from geometry.', 'The landing maps light one class of ball at a time — Serve · Return · Rally · End; nothing lit is every tracked ball. A feed-started rally session has no serve or return balls, so its track is Rally · End.', 'Shot speeds and stroke counts (forehands, backhands, volleys, overheads) appear on a SHOTS page only for matches that recorded them.'], reading: [
    'Placement is the habit; Landings is the reason. Read the table for what a player does and the map for where it goes wrong. A **crosscourt** share near 70% is a pattern the opponent has read by the second set; a **down the line** share under 15% is a player with no change of direction — the ball comes back to the same place every time.',
    '**Deep landings** under 40% is the depth problem the Aggression page hinted at with invited errors: the opponent is being handed short balls. Read it under the **Set** cut — depth that falls from set 1 to set 3 is a fitness or a nerve finding, not a technique one.',
    '**Forehands from own FH zone** under 60% is a player who runs around nothing and gives the forehand away; **into opponent’s FH zone** high is feeding the opponent’s strength — compare it with the opponent’s winners on the Points page. **Serves T · middle · wide** with one zone near 60% is a serve the returner can stand for; read it under **Deuce · Ad** and under **2nd** on the serve track to find the serve that always goes to the same place when it matters.',
    'Set the player’s **Zones** before trusting any of this: deep, middle and the forehand zone are the player’s own lines, and a junior’s deep line is not an adult’s.',
  ] },
]

const aggression: Group = { id: 'aggression', title: 'Aggression', page: 'AGGRESSION', lead: 'Whether a player is building points or giving them away — the classical aggressive margin, written out for how Rallymetrica tags a point.', theory: ['The aggressive margin is Bill Jacobsen’s statistic, from the CompuTennis charting of the 1980s. It starts from a fact about the sport: a point can only end three ways — a winner, a forced error, an unforced error — so from the winner’s side every point is a winner struck, an error forced from the opponent, or an error the opponent handed over. Jacobsen put the first two together as the points a player made happen and set the third against them. The margin is the net: points built minus points given away.', 'Craig O’Shannessy (Brain Game Tennis; strategy analyst to the ATP Tour and, for three seasons, to Novak Djokovic’s team) is the reason the margin matters more than the winners-to-unforced-errors ratio broadcasts quote. In his charting of the professional game, forced errors were 42% of all points, unforced errors 28% and winners 30%: seven points in ten end in an error, and the forced error — the category the ratio leaves out — is the single most common way a point ends. A statistic blind to forced errors is blind to the main thing a player is trying to do, which is make the opponent miss.', "Because every point is one of the three, the two players’ classical margins differ by exactly the point score: $\\mathrm{margin}_A-\\mathrm{margin}_B=\\mathrm{points}_A-\\mathrm{points}_B$. The margin is each player’s share of the scoreline, split into what was built and what was given — which is why the match winner all but always owns the higher margin, and why the rare exceptions are matches won on fewer points. The same margin can be reached two ways: 20 winners against 20 unforced errors and 5 against 5 are both zero, but the first player decided forty points and the second ten. Efficiency ($\\mathrm{built}/\\mathrm{given}$) gives the exchange rate; $\\mathrm{built}+\\mathrm{given}$ — the decided points — says how much of the match ran through that player’s racket.", 'The classical count charges a forced error to nobody but the attacker, so a player who feeds short balls all afternoon and is punished for it shows a clean sheet. Rallymetrica reads the landing before the error. A forced error that follows your own short, middle ball — not past the service line, in the middle third of the court — is invited: still the attacker’s point built, but also a point you gave. Every other forced error is pressured and stays the attacker’s alone. The cost is deliberate: charging invited errors to both sides means the two margins no longer differ by exactly the scoreline; the scoreline is on the cover, the margin is about responsibility. Tracked at Counter level there are no landings, every forced error reads as pressured, and the margin is Jacobsen’s to the point.'], rows: [
    { metric: 'Aggressive margin', how: 'built − given, signed, in points. Built: winners, aces, forced errors induced. Given: unforced errors, double faults, invited forced errors', needs: 'Counter', better: 'up' },
    { metric: 'Efficiency', how: 'built ÷ given — 1.0× is even; above it, a player built more than they gave away', needs: 'Counter', better: 'up' },
  ], notes: ['The invited / pressured split needs landings. A forced error you commit is invited when your own previous ball landed short and middle — not past the service line, and in the middle third of the court’s width. It counts −1 against you and +1 for the attacker. Every other forced error is pressured: the opponent beat a player who was in the point. It is shown in grey and not counted.', 'On a Counter match there are no landings, so every forced error reads as pressured — the opponent’s credit. The page says so: tracked without landings, forced errors read as the opponent’s.', 'The report page draws MARGIN or EFFICIENCY as a running line through the match — AGGRESSIVE above the EVEN line, YIELDING below, set by set — for both players or one. Beneath it, the headline per player and the counts the line is made of: AGGRESSIVE (aces, winners, forced opponent into error) and YIELDING (unforced errors, double faults, invited forced errors), so the court calls the margin rests on stay visible. Both rows read a dash under ten decided points.', 'A VS rally session carries the same page, block by block. A co-op has no winners and no forced · unforced split — every run ends with a miss — so it has no aggression page.'], reading: [
    'Read the two columns before the line. A big **built** column and a big **given** column is a player who decided the match, win or lose; two small columns is a player who made nothing happen and let the opponent decide. The same margin reached two ways — 20 against 20, 5 against 5 — is two different players.',
    'If **given** is the larger column, the split says which error to work on. Many unforced errors is margins and shot selection. Many **invited** forced errors is depth — the opponent did not beat the player, the player’s own short, middle ball invited the attack; the Placement page’s deep share will agree.',
    'A margin of +12 in a lost match is a player who built more than they gave and still lost: the points were lost somewhere the margin does not count — the pressure rows. A margin of −6 in a won match is a match won on the opponent’s gifts; the Momentum page’s Aggression currency shows when.',
    '**Efficiency** is the exchange rate, the margin is the volume. Compare players across matches by efficiency (1.4× is 1.4× in a short match or a long one); judge one match by the margin.',
  ], sample: { n: '10 decided points', why: 'below ten the rows read a dash; a one-set match rarely says anything about aggression, and three matches say more than one' } }

