function Pill({ level }: { level: Level }) {
  return <span className="inline-block rounded-full border border-accent/25 px-2 py-0.5 text-[10px] font-semibold tracking-[.12em] text-accent uppercase">{level}</span>
}

function RowsTable({ rows }: { rows: Row[] }) {
  return <div className="mt-5 overflow-hidden rounded-2xl border border-line"><div className="hidden grid-cols-[1fr_1.6fr_96px] gap-4 border-b border-line bg-surface px-5 py-3 sm:grid"><span className="eyebrow text-muted">Metric</span><span className="eyebrow text-muted">How it is counted</span><span className="eyebrow text-muted">Needs</span></div>{rows.map(row => <div key={row.metric} className="grid gap-2 border-b border-line px-5 py-4 last:border-b-0 sm:grid-cols-[1fr_1.6fr_96px] sm:gap-4"><div className="flex items-start justify-between gap-3"><span className="text-sm font-semibold text-ink">{row.metric}{row.better === 'down' && <span className="ml-2 text-xs font-normal text-muted">fewer is better</span>}</span><span className="sm:hidden"><Pill level={row.needs} /></span></div><span className="text-sm">{row.how}</span><span className="hidden sm:block"><Pill level={row.needs} /></span></div>)}</div>
}

function CatalogueGroupContent({ group }: { group: Group }) {
  return <><RowsTable rows={group.rows} />{group.notes && <ul className="mt-5 list-disc space-y-2 pl-5 text-sm">{group.notes.map(note => <li key={note}>{note}</li>)}</ul>}{group.reading && <div className="mt-6 rounded-2xl border border-accent/15 bg-accent/[.04] p-5"><p className="eyebrow text-accent">Reading it</p><ul className="mt-3 list-disc space-y-2 pl-4 text-sm">{group.reading.map(item => <li key={item} dangerouslySetInnerHTML={{ __html: item.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>') }} />)}</ul>{group.sample && <p className="mt-4 text-xs leading-5 text-muted"><span className="font-semibold text-ink">Enough to read · {group.sample.n} — </span>{group.sample.why}.</p>}</div>}</>
}

export default function StatsEnginePage() {
  return <Container className="py-12 sm:py-16">
    <Link href="/learn" className="text-sm text-muted hover:text-accent">← All guides</Link>
    <div className="mt-10 grid gap-12 lg:grid-cols-[220px_1fr] lg:gap-14">
      <aside className="hidden lg:block"><nav aria-label="On this page" className="sticky top-8"><p className="eyebrow mb-6 text-accent">The stats engine</p>{sections.map(section => <a href={`#${section.id}`} key={section.id} className="block border-l border-line py-2.5 pl-4 text-sm leading-6 text-muted hover:text-ink">{section.title}</a>)}<p className="eyebrow mt-8 mb-4 text-accent">Guides</p><Link href="/learn/stats-and-trends" className="block border-l border-line py-2.5 pl-4 text-sm leading-6 text-muted hover:text-ink">See your progress over time</Link><Link href="/learn/reports-and-replay" className="block border-l border-line py-2.5 pl-4 text-sm leading-6 text-muted hover:text-ink">Read the match. Revisit the rally.</Link><Link href="/learn/serve-sessions" className="block border-l border-line py-2.5 pl-4 text-sm leading-6 text-muted hover:text-ink">Serve sessions: a basket at a target</Link><Link href="/learn/coop-sessions" className="block border-l border-line py-2.5 pl-4 text-sm leading-6 text-muted hover:text-ink">Co-op sessions: count the run</Link></nav></aside>
      <article className="guide-copy min-w-0">
        <header className="max-w-3xl"><div className="eyebrow flex gap-4 text-accent"><span>Reference</span><span className="text-muted">30 min read</span></div><h1 className="mt-5 text-4xl leading-[1.12] font-semibold tracking-[-.05em] text-ink sm:text-5xl">The stats engine.<br /><span className="text-accent">Every number, defined.</span></h1><p className="mt-6 text-lg leading-8">Rallymetrica computes every statistic from the points you record, under the rules of the match. Nothing is estimated from video or sensors: a number exists only when the point data behind it was tapped. This page lists what the engine measures, how each metric is defined, which tracking level it needs, what changes on a practice session, and how the Stats tab turns a run of matches into a trend.</p></header>

        <section id="levels" className="mt-14 scroll-mt-8 border-t border-line pt-8"><h2 className="text-2xl font-semibold tracking-tight text-ink">What each tracking level unlocks</h2><p className="mt-4 text-sm">The tracking level is chosen at match setup and can be changed during the match; the new level applies to that match. Each level includes everything below it. Practice sessions are always Detailed.</p><div className="mt-8 grid gap-5 md:grid-cols-3">{levels.map(level => <div key={level.name} className="rounded-2xl border border-line bg-surface/60 p-6"><p className="eyebrow text-accent">{level.name}</p><p className="mt-4 text-sm">{level.what}</p><p className="mt-5 text-xs leading-6"><span className="font-semibold text-ink">Unlocks · </span>{level.unlocks}</p></div>)}</div><div className="mt-8 grid gap-6 sm:grid-cols-3"><figure><AppScreenshot name="live-score" alt="The live court in Score mode" className="mx-auto w-full max-w-[200px]" /><figcaption className="mt-3 text-center text-xs">Score</figcaption></figure><figure><AppScreenshot name="live-counter" alt="The live court in Counter mode" className="mx-auto w-full max-w-[200px]" /><figcaption className="mt-3 text-center text-xs">Counter</figcaption></figure><figure><AppScreenshot name="live" alt="The live court in Detailed mode" className="mx-auto w-full max-w-[200px]" /><figcaption className="mt-3 text-center text-xs">Detailed</figcaption></figure></div></section>

        <section id="catalogue" className="mt-14 scroll-mt-8 border-t border-line pt-8"><h2 className="text-2xl font-semibold tracking-tight text-ink">The catalogue</h2><p className="mt-4 text-sm">One catalogue feeds the report’s tables, the player profile’s trends and the Stats tab’s chart, so a row means the same thing everywhere. Each row knows which direction is better; a report table lights the better side. Ratios show the fraction beneath the percentage. A record kind removes whole dimensions before any row is asked — a rally session has no situation or score, a feed-started one no serve — and what it cannot hold is absent, never greyed.</p><div className="mt-6 rounded-2xl border border-line bg-surface/60 p-5"><p className="eyebrow text-accent">How to read a report, in order</p><ol className="mt-3 list-decimal space-y-2 pl-5 text-sm"><li><strong>Cover</strong> — the format block first: the standard the numbers are judged against.</li><li><strong>Momentum</strong> — the shape of the match and the starred swing. Tap it: did the win chance move with the share of points, or without it?</li><li><strong>Aggression</strong> — who was dictating, and whether the errors were given or invited.</li><li><strong>Points · Serve · Return</strong> — the rows in pairs and chains, the fraction under every percentage.</li><li><strong>Pressure</strong> — each row against Points won; the gap is the finding.</li><li><strong>Placement · Landings</strong> — the habit in the table, the reason on the court.</li><li><strong>One cut, then Stats</strong> — the narrower question, then the same row across ten matches before anything changes in practice.</li></ol><p className="mt-4 text-xs leading-5 text-muted">Every group below ends with a <em>Reading it</em> box: the rows to read against each other and what the gap between them says. The Practice-plan guide walks the same order on a real report.</p></div>
          {groups.map(group => <div id={group.id} key={group.id} className="mt-12 scroll-mt-8"><div className="flex flex-wrap items-baseline justify-between gap-3"><h3 className="text-xl font-semibold text-ink">{group.title}</h3><span className="eyebrow text-muted">Report page · {group.page}</span></div><p className="mt-3 text-sm">{group.lead}</p>{group.id === 'placement' ? <div className="stats-section-layout mt-6"><div className="stats-section-content min-w-0"><CatalogueGroupContent group={group} /></div><figure className="stats-section-figure"><AppScreenshot name="landings" alt="The report’s Landings page: the court maps" className="mx-auto w-full max-w-[230px]" /><figcaption className="mt-3 text-center text-xs">LANDINGS · the placement rows drawn on the court</figcaption></figure></div> : <CatalogueGroupContent group={group} />}</div>)}
        </section>

        <section id="aggression" className="mt-14 scroll-mt-8 border-t border-line pt-8"><div className="flex flex-wrap items-baseline justify-between gap-3"><h2 className="text-2xl font-semibold tracking-tight text-ink">Aggression</h2><span className="eyebrow text-muted">Report page · {aggression.page}</span></div><div className="stats-section-layout mt-6"><div className="stats-section-content min-w-0 space-y-4 text-sm"><p>{aggression.lead}</p>{(aggression.theory ?? []).map(p => <p key={p}><MathText text={p} /></p>)}<MathFormulas formulas={statsMath.aggression} /><h3 className="mt-10 text-base font-semibold text-ink">The two rows</h3><RowsTable rows={aggression.rows} /><ul className="mt-5 list-disc space-y-2 pl-5 text-sm">{(aggression.notes ?? []).map(note => <li key={note}>{note}</li>)}</ul>{aggression.reading && <div className="mt-6 rounded-2xl border border-accent/15 bg-accent/[.04] p-5"><p className="eyebrow text-accent">Reading it</p><ul className="mt-3 list-disc space-y-2 pl-4 text-sm">{aggression.reading.map(item => <li key={item} dangerouslySetInnerHTML={{ __html: item.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>') }} />)}</ul>{aggression.sample && <p className="mt-4 text-xs leading-5 text-muted"><span className="font-semibold text-ink">Enough to read · {aggression.sample.n} — </span>{aggression.sample.why}.</p>}</div>}</div><figure className="stats-section-figure"><AppScreenshot name="aggression" alt="The report’s Aggression page: the margin per game for both players" className="mx-auto w-full max-w-[230px]" /><figcaption className="mt-3 text-center text-xs">AGGRESSION · aggressive above EVEN, yielding below</figcaption></figure></div></section>

        <section id="momentum" className="mt-14 scroll-mt-8 border-t border-line pt-8"><h2 className="text-2xl font-semibold tracking-tight text-ink">Momentum</h2><div className="stats-section-layout mt-6"><div className="stats-section-content min-w-0 space-y-4 text-sm"><p>The momentum curve is the probability that a player goes on to win the match, recomputed after every point from the <strong>exact score</strong> and the rules in force — set format, tiebreak, no-ad. The serve-point rates behind it start from the player’s history and update as the match goes on; the rates steady, the curve does not — late points in a close match move it most. Only Score tracking is needed.</p><p><strong>Swings</strong> are the moments the curve changed course most. The engine finds the change points, weighs each by how much was riding on it, and marks the strong ones with a disc, the weak ones with a ring and the largest with a star. Tap a swing to compare the stretch before it with the stretch after: points played and win chance for each player.</p><p><strong>Live</strong>, the curve extends as points arrive. Under a cut, momentum highlights rather than filters: a set cut fades the other sets, a score or situation cut beads the curve at those points — blue where the first player won them, green the second.</p><h3 className="mt-8 text-base font-semibold text-ink">Two currencies: POINTS · AGGRESSION</h3><p>The page draws momentum in two currencies, switched under the legend. <strong>POINTS</strong> is the win-advantage curve described below, with its swings and the swing table; it needs only the score. <strong>AGGRESSION</strong> is a form line and needs a Counter match: each point scores +1 if the player built it (a winner, an ace, a forced error drawn) and −1 if they gave it (an unforced error, a double fault, an invited forced error), and the line is an exponentially weighted average of those scores over roughly the last twelve points — the most recent count most, so the line remembers the last few games and forgets the first set. With BOTH players shown it is one player’s form minus the other’s: above EVEN, the player named at the top has been the more efficient lately. With one player picked it is that player alone: above EVEN they have been building more than giving. The AGGRESSION report page’s own line is the running built ÷ given for the whole match so far, so it settles; the momentum form line is meant to move. No swings or table on that view.</p><h3 className="mt-8 text-base font-semibold text-ink">The model behind the POINTS curve</h3><p>Tennis has had a working probability model since the early 1970s, because the game is a ladder of small contests — point, game, set, match — and once you know how often each player wins a point on their own serve, every rung follows by the same arithmetic. Hsi and Burych (1971) and Carter and Crews (1974) worked out the game and the set; Klaassen and Magnus (2003) turned the ladder into a forecast updated point by point, which is what this curve is.</p><p>Call <MathNotation tex={statsInlineMath.p} /> the chance the first player wins a point on serve and <MathNotation tex={statsInlineMath.q} /> the second player’s. From deuce a server holds with <MathNotation tex={statsInlineMath.deuceHold} />: at <MathNotation tex={statsInlineMath.pExample} /> that is 69%, from the start of the game 74%, and 71% under no-ad, where one point decides deuce. Ten points in a hundred above even on the point become twenty-four above even on the game; the ladder amplifies. The same recursion climbs: hold-or-break probabilities give the set under its format — advantage sets, a tiebreak at 6–6 with its own serve rotation, no-ad with one point deciding deuce — and sets give the match. The curve’s value after a point is the match probability from the exact score reached.</p><p>Nobody knows <MathNotation tex={statsInlineMath.p} /> and <MathNotation tex={statsInlineMath.q} /> before the match. The engine starts each from the player’s history in the order played — a morning match informs the afternoon’s — itself shrunk toward the tour’s 62% while that history is short, with the same weight <MathNotation tex={statsInlineMath.kappa} /> — counted as if it were <MathNotation tex={statsInlineMath.kappa} /> serve points of evidence, and adds the match’s own serve points one by one: <MathNotation tex={statsInlineMath.liveRate} />, and <MathNotation tex={statsInlineMath.otherRate} /> the same from the other player’s serve. The match’s weight is <MathNotation tex={statsInlineMath.matchWeight} />, so history matters most in the first games and fades as serve points accumulate. The estimates steady as the match goes on; the curve itself does not — late points in a close match carry more, so it can swing hardest at the end.</p><p>How far a point can move the curve is its <strong>importance</strong>, in Morris’s sense (1977): the win probability if the point is won minus the win probability if it is lost, both read with the rates as they stood before the point. At <MathNotation tex={statsInlineMath.equalRatesExample} /> in a best-of-three, 30–0 in the first game is worth about two points of match probability; a break point at 5–5 in a full deciding set can swing a third of the match (half that in an earlier set; under a match tiebreak the decider is priced differently). The curve moves by importance times surprise — one minus the chance of winning the point if it was won, minus the chance if it was lost — so winning a point you were favoured to win moves it less than losing it would have: at that 30–0, about +0.7 up or −1.1 down. The swing finder reads the curve for its turning points — where a run of one player’s points gives way to a run of the other’s — ranks them by how far the curve moved, ignores zigzags too small or too close together, and stars the largest. In a live match the newest turn is provisional until the next points confirm it, and stays listed beside the largest even when it would not yet rank among them. A short turn built of break points outranks a long one built of 30–0s because the curve moved further, not because anyone weighted it.</p><p>Momentum here is the broadcast sense — where the match stands and how it got there — not a claim that winning a point changes the next one. The evidence on that is modest. Klaassen and Magnus (2001), on professional matches at Wimbledon, found that points are not quite independent: winning the previous point raises the chance of winning the next by a little, and servers win fewer of the important points than of the ordinary ones. Both effects are small, and a model that ignores them forecasts almost as well. So the curve treats each point on its merits, and the swings show where the run happened without saying why.</p><h3 className="mt-8 text-base font-semibold text-ink">On a rally session: a race, not a score</h3><p>A rally game has a tally, not 0–15–30–40, so the tennis ladder cannot read it. The curve is instead the probability of <strong>reaching the target first</strong> from the current tally, with the point-win rate learned from the session’s own points (smoothed around ½ with a weight of 24 points), then the blocks as trials to a majority. A timed session reads the probability of leading when time runs out, the remaining points estimated from the pace so far. Importance and swings follow from that curve exactly as a match’s do. A co-op has no winner to model and draws its runs instead.</p><MathFormulas formulas={statsMath.momentum} /><div className="rounded-2xl border border-accent/15 bg-accent/[.04] p-5"><p className="eyebrow text-accent">Reading it</p><ul className="mt-3 list-disc space-y-2 pl-4"><li>The starred swing is the largest the curve made. Tap it and compare the two stretches: if your win chance fell while your share of points barely moved, you lost the big points, not the rallies — go to PRESSURE.</li><li>A swing made of break points at 4–4 outranks a longer run at 1–0 because the curve moved further. Judge the match by the swings, not by how long each run lasted.</li><li>On AGGRESSION, a form line under EVEN while the POINTS curve still rises means the points are coming from the opponent’s gifts, not from you building them — a lead that is not yours to keep.</li><li>Under a set cut the other sets fade rather than vanish, so a swing can be read against the whole match.</li></ul></div></div><figure className="stats-section-figure"><AppScreenshot name="momentum" alt="The report’s Momentum page with the curve and its swings" className="mx-auto w-full max-w-[230px]" /><figcaption className="mt-3 text-center text-xs">MOMENTUM · the largest swing starred</figcaption></figure></div></section>

<section id="forecast" className="mt-14 scroll-mt-8 border-t border-line pt-8"><h2 className="text-2xl font-semibold tracking-tight text-ink">Forecast</h2><div className="stats-section-layout mt-6"><div className="stats-section-content min-w-0 space-y-4 text-sm"><p>Rallymetrica forecasts two different things, and it is worth knowing which one you are looking at. A <strong>row forecast</strong> says where one of your numbers — first serves in, unforced errors, aces — should land in your next match, from your own history of that number and nothing else. A <strong>match forecast</strong> says how likely you are to win, from both players’ serve rates run through the arithmetic of the scoring system. They share one engine and one rule — nothing is said without its range — but they answer different questions, and the Win rate row is where the two meet.</p><h3 className="mt-8 text-base font-semibold text-ink">Row forecasts: one number, its own history</h3><p>Every row the Stats tab charts can be read one match ahead. On the Stats tab the third view, <strong>FORECAST</strong>, draws a dashed <strong>baseline</strong> through the chart — the forecast as it stood before each match — and, one slot past the last match, a <strong>star</strong> for the next one with its 80% range as a bar. Each dot is coloured against the baseline it had: yellow above, coral below. The legend names the model that fitted — <em>Forecast · level</em>, <em>trend</em>, <em>trend, damping</em> — and the star’s popover gives the number, its range and the matches it came from. The window (Last 3 · 7 · 10 · All) decides how much of the curve you see, never what the model knows: the forecast is always built from your whole history under the current cut, so Last 3 shows three dots and the same star All shows.</p><p>The method is exponential smoothing in its state-space form — ETS, Hyndman’s family — restricted to the three members a short, irregular series can carry: a <strong>level</strong> that updates with each match, a level with a <strong>trend</strong>, and a trend that <strong>fades</strong> (damped). Each is fitted by maximum likelihood — the smoothing weights and the starting state together — and the member is chosen by the small-sample information criterion (AICc), which charges every parameter, the starting state and the error variance included, so a slope must earn its place. Seasonal terms, ARIMA and anything neural are ruled out by the data: five to forty matches, weeks apart, teach none of them.</p><p>A short series tempts the fit to the boundary — a smoothing weight of one is “the next match will be the last one”, which is no forecast. So the weight is estimated first and then shrunk toward the roster’s — the median weight of the players with eight or more matches on that row, else 0.3 — with a strength <MathNotation tex={statsInlineMath.kappa} /> of eight: a player with six matches borrows the smoothing the roster has earned; at thirty the estimate stands nearly whole. The member is refitted at the shrunk weight, so the shrinkage constrains what is drawn, not merely what was searched.</p><h3 className="mt-8 text-base font-semibold text-ink">The baseline is honest</h3><p>The forecast for a match is made from the matches before it alone — parameters, member, starting state and the roster’s weight as they stood that day — and kept. A later result never rewrites an earlier forecast, and the first five matches carry none: a baseline that could see the future would flatter itself. It is the discipline the model is held to on real matches too — a rolling origin, scored against the last value, the pooled mean and a recency-weighted mean, by error, by how often the range held and by how wide it had to be.</p><h3 className="mt-8 text-base font-semibold text-ink">The range</h3><p>The range is the model’s own uncertainty one step ahead — the state-space variance of the member, read at the same one-sided 90% point as the usual range, so the middle 80%. It never collapses: five identical matches do not establish certainty about the sixth, so the variance has a floor — a rate’s binomial noise over the points it was counted on, a count’s Poisson noise, two points for a bare percentage or a margin, or the roster’s residual spread while the history is short.</p><h3 className="mt-8 text-base font-semibold text-ink">Match forecasts: two players, one scoring system</h3><p>A match is not a number with a history; it is two players and a format. So the match forecast starts from one input per player — their <strong>serve-point win rate</strong>, itself a row forecast of that one row, counted in serve points from their own matches; while that history is short the rate leans toward the tour’s 62% (the momentum model’s own prior — with one match the lean is strong, with twenty it is almost gone, so nothing jumps at the fifth match) — and runs the two rates through the scoring model from the current score: every remaining game, tiebreak and set, summed exactly under the match’s rules. There are no hand-tuned weights between the rates and the chance; the arithmetic of tennis does the rest.</p><p><strong>What feeds the rates is decided by evidence, and it is growing.</strong> Today the input is the serve-point rate alone. The next version of the model tests four richer forms against it on real matches, chronologically held out: the serve split into first serves in, points won behind the first and behind the second (so double faults get a mechanism of their own); recent unforced-error form, serve and return apart, measured against the player’s own baseline; recent aggression form — winners, aces and errors forced against points given away; and the plain rate as the baseline they must beat. An input earns its place only by forecasting held-out matches better — by log loss, Brier score and how often its ranges held — and the simpler model wins a tie. What survives feeds the rates; the scoring arithmetic above never changes. The report’s live FORECAST table already shows errors and winners against their own forecasts, so a coach can read today what the model will learn to weigh. Out come the win chance with its 80% range, the most likely set score, the expected length, and each player’s expected points and break chances — a player who wins every point of a best-of-three is 6–0 6–0, forty-eight points, six break points, and the model says so.</p><p>The range is honest about how steep that arithmetic is. A five-point gap in serve rates can move the win chance twenty points, so a linear approximation would run past 0 and 100. Instead the two rates’ uncertainties are pushed <em>through</em> the scoring model as a distribution, and the range is the middle 80% of where the win chance lands — inside 0 and 100 by construction, narrowing only as the rates’ evidence grows. An opponent with no history carries the tour rate and a wide range. The words follow the range, never the number alone: <em>Asiya likely · 54–71%</em>; <em>Even match</em> whenever the range covers a half — a real answer, and the usual one between well-matched players.</p><h3 className="mt-8 text-base font-semibold text-ink">The forecast lives through the match</h3><p>The pre-match forecast is the first point of the live one. As points are played, the same two rates update with what is happening on court and the same arithmetic reads the chance from the exact score, so the number you saw before the first point and the one you see at 4–4 in the second set are one continuous thing — and the win-probability curve on the MOMENTUM page is that thing drawn over time. Three places show it, and only while the match is live. On the <strong>live match card</strong> a <strong>FORECAST</strong> chip in the footer reads the leader and the chance — <em>LINDQVIST 55%</em>, or <em>EVEN</em> — and tapping it flips the card over: the headline, both players’ serve points won and unforced errors so far, and <em>Back to score</em>. The <strong>live report’s cover</strong> carries a FORECAST section under the match facts: the headline, then a two-sided table of the rows a forecast can speak to — first serve in, serve points won, unforced errors, winners, double faults — each player’s number now against their own forecast, and for counts the pace they are on (<em>13 · 30→37</em> is thirteen errors so far, thirty expected, on pace for thirty-seven). When the match closes, the forecast goes; what the match did against its forecasts lives on as the dots on the Stats tab.</p><h3 className="mt-8 text-base font-semibold text-ink">Win rate: where the two meet</h3><p>Win rate is the one row whose forecast is a match forecast. A smoothed line through wins and losses would know nothing about who you played; the match model does. So each past dot’s baseline is what the match model said <em>before that match</em> — the real opponent, the real format, the two serve rates as they stood that day — and its colour reads whether the result was expected. The star is your chance to win your <em>next</em> match: the scoring model run once against every opponent you have faced, at their current rates, and the chances averaged by how often you face each — never the opponents averaged into one imaginary player, because the arithmetic is too steep for that to mean anything. It lags a player who is climbing a level, as every forecast built on history must; the range says how sure it is. And because every baseline on that row is a real pre-match forecast, the Win rate page is also where the match model is judged — by how often its ranges held and how sharp they were.</p><p>Both kinds of forecast obey the same floor: nothing is forecast from fewer than five matches, and a trend is not allowed before eight. Until then the legend reads <em>Forecast needs 5 matches</em>, the card shows no chip, and the cover carries no section.</p><MathFormulas formulas={statsMath.forecast} /><div className="rounded-2xl border border-accent/15 bg-accent/[.04] p-5"><p className="eyebrow text-accent">Reading it</p><ul className="mt-3 list-disc space-y-2 pl-4"><li>Know which forecast you are reading. A row forecast is about one of your numbers and knows nothing of the opponent; a match forecast is about the two of you and the format.</li><li>Read the gap, not the dot. <em>+4 vs forecast · forecast was 58%</em> is a match that beat what the last ones predicted; a season of small positive gaps is improvement the average cannot see yet.</li><li>A wide range is a consistency problem, a narrow one a repeatable level. The range narrows as a player’s matches agree with each other — never merely because there are many of them.</li><li>During a match, the cover’s FORECAST table is the fastest read of why the chance is moving: serve points won above the forecast and the chance is up; errors on pace past the forecast and it is down.</li><li><em>Trend, damping</em> in the legend is the model saying the run will not continue at this pace: read it as a level still moving, not a line to extrapolate.</li><li>A match forecast is a range. <em>54–71%</em> says the coin is loaded, not that the match is decided; <em>Even match</em> is a real answer.</li></ul></div></div><figure className="stats-section-figure"><AppScreenshot name="forecast" alt="The Stats tab’s FORECAST view: the dashed baseline before each match, the next match starred with its range" className="mx-auto w-full max-w-[230px]" /><figcaption className="mt-3 text-center text-xs">STATS · FORECAST — the baseline before each match, the next one starred</figcaption></figure></div></section>

        <section id="patterns" className="mt-14 scroll-mt-8 border-t border-line pt-8"><h2 className="text-2xl font-semibold tracking-tight text-ink">Patterns</h2><div className="stats-section-layout mt-6"><div className="stats-section-content min-w-0 space-y-4 text-sm"><p>A pattern of play is a sequence of two to four landing zones drawn by a coach and assigned to a player. Up to three patterns are selected per player in a Detailed match setup — or a rally session’s; the engine then matches every recorded point against them.</p><p>An <strong>attempt</strong> is counted when a point reaches the pattern’s opening zone with the right player hitting and the right serve context (any, first or second serve, when the pattern opens with a serve). A <strong>completion</strong> means the full sequence of zones was recorded, in order; consecutive landings must alternate sides. Each pattern counts at most once per point.</p><p><strong>3 of 7 attempts · 67% won</strong> reads: three complete executions from seven openings, and two of those three points won. The percentage is points won <em>after completion</em>, which is the question a coach is asking. A match keeps the patterns selected at its start; later edits do not rewrite its results. Player profiles bring the results together across Detailed matches. A co-op session reads completions of attempts with no points won — there are none to win. Serve sessions carry no patterns.</p></div><figure className="stats-section-figure"><AppScreenshot name="profile-patterns" alt="A player profile’s Patterns tab with completions out of attempts" className="mx-auto w-full max-w-[230px]" /><figcaption className="mt-3 text-center text-xs">Profile › PATTERNS · across matches</figcaption></figure></div></section>

        <section id="practice" className="mt-14 scroll-mt-8 border-t border-line pt-8"><h2 className="text-2xl font-semibold tracking-tight text-ink">Practice sessions</h2><div className="stats-section-layout mt-6"><div className="stats-section-content min-w-0 space-y-4 text-sm"><p>A session is a record of the same kind as a match — the same players, the same court and taps, the same engines — without sets, games or a server’s rotation. Three shapes: a <strong>VS rally</strong> (one rally, one point; a tally in blocks, timed, or open; started by a serve or a feed), a <strong>co-op</strong> (two players keep the ball in play; any miss ends the run), and a <strong>serve session</strong> (one server, blocks of serves at a target). Sessions are always Detailed.</p><h3 className="mt-8 text-base font-semibold text-ink">A VS rally reads the match catalogue</h3><p>Its report is the match report with blocks for sets: Momentum (the race model above), Aggression, Points, Placement, Landings, Patterns, Timeline. What a tally cannot hold is absent: no Pressure page, no break-point row, no situation or score cut. Serve and Return appear only when the session started with a serve — a feed-started rally has no serve ball, so the serving · returning track, the serve zones and the Serve · Return ball classes are gone too. On a one-serve session (the second-serves-only drill) a fault loses the point: the double-fault row reads <strong>Faults</strong>, the second-serve rows are absent, and there is no Return page.</p><h3 className="mt-8 text-base font-semibold text-ink">A co-op counts runs</h3><p>There are no winners and no forced · unforced split — every run ends with a miss by the player who hit the last ball. <strong>RUNS</strong> draws every run in order as a bar, the longest lit, with the average and the median as lines and the session’s cells beneath: runs, longest, shortest, average, median, runs over 10, balls, and balls a minute over the lit runs’ seconds — so a cut narrows the pace with the count. Per player: balls hit, balls a minute, runs ended, and the average, median and longest run they ended. <strong>ENDINGS</strong> takes the Points page’s place: runs ended, into the net, long, wide, unplayable (in, but the partner could not play it), balls hit.</p><h3 className="mt-8 text-base font-semibold text-ink">A serve session has its own catalogue</h3><p>Two numbers lead: <strong>IN %</strong> (was the serve good — in PAIRS, the share of points that ended with a serve in) and <strong>ON TARGET %</strong> (of the serves in, the share in the block’s target zone). The table beneath them:</p><RowsTable rows={serveRows} /><p>Its cuts are its own — <strong>block</strong>, <strong>1ST · 2ND</strong> (PAIRS only), <strong>DEUCE · AD</strong> (when both sides were served) and the <strong>type</strong> (when any serve was typed) — one track on every page, and none of the match cuts. A row that a cut would empty or merely restate is greyed, as on a match: the first-serve rows under 2ND, the type shares under a type.</p><h3 className="mt-8 text-base font-semibold text-ink">Streaks, accuracy and the two lines</h3><p><strong>TREND</strong> draws the session on one axis after every serve: the running <strong>in share</strong> (serves in so far ÷ serves so far), the running <strong>on-target share</strong> (of the serves in so far, those in the called zone) and the <strong>streak</strong> so far (consecutive serves in, reset by a fault). STREAKS · TARGET beneath the chart picks the reading. The streak is the measure of repeatability the percentage hides: 70% in with a longest streak of 3 is a serve that goes in but not twice running; 60% in with a streak of 9 is a serve that was grooved for a stretch and lost. On STREAKS the <strong>mean</strong> and <strong>median</strong> of the in-streaks sit as lines — the same two lines as a co-op’s runs: the median is the typical streak, the mean is lifted by the long ones, and the gap between them is how much of the session was one good patch. On TARGET the curve’s direction is the finding — climbing, a serve settling into the zone as the basket goes on; falling, fatigue, or a target the server does not have yet. The streak reads under the block cut alone; a 1ST · 2ND, side or type cut skips serves, so consecutive loses its meaning and the row reads a dash.</p><h3 className="mt-8 text-base font-semibold text-ink">Reading a co-op’s two lines</h3><p>The RUNS chart’s <strong>average</strong> and <strong>median</strong> are two summaries of the same runs, and the distance between them is the insight. Runs are skewed: most are short, a few are long. The median is the run to expect — half were longer, half shorter — and does not move when one run reaches forty. The mean does. <em>Average 14 · median 9</em> is a pair that can rally but not on demand; <em>average 10 · median 9</em> is a steady pair with a lower ceiling. <strong>Over 10</strong> counts the runs that passed ten balls, the target coaches set (“five over ten”). <strong>Balls a minute</strong> is tempo over the lit runs’ own seconds: a cut by block compares the pace of the first block with the last and says whether the pair tired or settled. The per-player rows attribute the endings: the player who ends the short runs misses early, the one who ends the long runs loses the thread late.</p><p>The Stats tab charts matches only; a session’s trend is its own report’s.</p></div><figure className="stats-section-figure"><AppScreenshot name="serve-report" alt="The serve report’s Trend page: streaks and accuracy over the session" className="mx-auto w-full max-w-[230px]" /><figcaption className="mt-3 text-center text-xs">SERVE REPORT › TREND · streaks and accuracy on one axis</figcaption></figure></div></section>

        <section id="cuts" className="mt-14 scroll-mt-8 border-t border-line pt-8"><h2 className="text-2xl font-semibold tracking-tight text-ink">Cuts: asking a narrower question</h2><p className="mt-4 text-sm">Every table page, TIMELINE, MOMENTUM and LANDINGS carry the same filter track; so does the Stats tab. A cut keeps only the points that fit, and every row is recomputed from them.</p><ul className="mt-5 list-disc space-y-3 pl-5 text-sm"><li><strong>Set</strong> — S1 … S5, the sets the match played; on a rally session the blocks, B1 … B5.</li><li><strong>Situation</strong> — one at a time: {situations.map(([name, meaning], index) => <span key={name}>{index > 0 && '; '}<strong>{name}</strong> ({meaning})</span>)}.</li><li><strong>Score</strong> — the game score before the point, read server first: the presets First point · 30–30 · Deuce · Advantage, or any pair on the two wheels. A score cut rests under a point situation and stays live inside a game situation — “30–30 points inside break games”.</li><li><strong>The page’s own tracks</strong> — Serving · Returning; rally length 0–4 · 5–8 · 9+ (a point property, so under a serve view 9+ reads “where the serves landed in points that became long rallies”); starred points; on the serve and return pages Deuce · Ad and T · Mid · Wide; on the landing maps Serve · Return · Rally · End, one class of ball at a time.</li></ul><p className="mt-5 text-sm">An option greys out when no row on the page can use it, or when it could not change the row — rally length on aces, break point on break points. PRESSURE turns the score cut off because each row names its own score; COVER and PATTERNS take no cuts; Win rate takes none. A dimension the record cannot hold is absent rather than greyed: a rally session has no Situation or Score, a feed-started one no serving · returning, a co-op no period cells; a serve session carries its own track (above) and none of these.</p></section>

        <section id="over-time" className="mt-14 scroll-mt-8 border-t border-line pt-8"><h2 className="text-2xl font-semibold tracking-tight text-ink">Stats over time</h2><div className="stats-section-layout mt-6"><div className="stats-section-content min-w-0 space-y-4 text-sm"><p>The Stats tab charts one catalogue row across a window of matches, so a number you saw on one report becomes a question about you: is this where I usually land, and which way is it moving? On Free and Player the subject is you; on Coach, any player on the roster. Choosing an opponent narrows the window to that head-to-head; on Coach, picking two players and a common opponent draws both as series on one axis. Matches only: a practice session is not charted here — its trend is its own report’s (TREND on a serve session, RUNS on a co-op).</p><p>The <strong>window</strong> is Last · 3 · 7 · 10 · All, shared with the profile’s Trends. Each match’s value is computed from that match’s own points under the same cuts — the chart is the report, repeated. A dotted gap is a match that did not capture the row (a Score match has no first-serve percentage); it is never a zero.</p><h3 className="mt-8 text-base font-semibold text-ink">Three views, three questions</h3><p><strong>MA</strong> answers <em>where is my normal?</em> It draws the window mean as a flat line. <strong>TREND</strong> answers <em>which way is it moving?</em> It fits a straight line through the matches by least squares and states the slope in the legend: <em>−1.6% per match</em> means the row has drifted down about a point and a half each match — roughly fourteen points across a ten-match window. The moving average needs two matches, the trend three.</p><p><strong>FORECAST</strong> answers <em>what should the next one be?</em> — and, read backwards, <em>was this match above or below what the last ones predicted?</em> It is its own section: <a href="#forecast" className="text-accent">Forecast</a> — two kinds, a row forecast from a number’s own history and a match forecast from both players through the scoring system, and the Win rate row where they meet. In short: a dashed baseline that is the forecast as it stood before each match, a star for the next one with its 80% range, five matches needed and eight before a slope; the window shows the curve’s tail, never less history to the model.</p><h3 className="mt-8 text-base font-semibold text-ink">The usual range</h3><p>The shaded band is the <strong>usual range</strong>: the middle 80% of where a normal match for this player lands. It is a prediction band, not a confidence band. The question is not “how well do we know the average?” but “was today a normal day for me?”, which is about the next match — so the band carries the scatter of a single match: half-width <MathNotation tex={statsInlineMath.usualRange} />, with <MathNotation tex={statsInlineMath.spread} /> the spread of the window’s matches and <MathNotation tex={statsInlineMath.quantile} /> the one-sided 90% value for that many matches, which leaves 10% above and 10% below. Around the trend the same band follows the line and is slightly wider at the ends, where the line is least certain. It needs five matches; before that there is no honest range to draw. Under FORECAST the range is the model’s own — the spread of its one-step errors, read with the same one-sided 90% value — and it never collapses to nothing: five identical matches still leave the next one a range, floored at a rate’s binomial noise over its points or a count’s Poisson noise.</p><p>Why 80% and not 95%? At seven matches a 95% band is wider than the chart, so every match is “normal” and the band says nothing. At 80%, one match in five falls outside by construction: outside means a top-tenth or bottom-tenth day for this player. Inside is a normal day, outside is notable — that is the whole reading.</p><h3 className="mt-8 text-base font-semibold text-ink">The colours</h3><p>The line is one quiet line; the <strong>dots</strong> carry the verdict — <strong>yellow</strong> where a match sits above the average, the trend or the forecast, <strong>coral</strong> where it sits below. Colour is relative to the player’s own line, never to a good or bad number: a 55% that beats a 50% average is yellow. The model lines — average, trend, forecast — are dashed; the band is a grey tone with dashed edges. A match in progress is the last, hollow point with the pink pulse and LIVE above it, joined by a dashed lead; it is drawn but left out of the mean, the trend, the band and the forecast until it finishes. Tap any dot for that match’s card and its report.</p><div className="rounded-2xl border border-accent/15 bg-accent/[.04] p-5"><p className="eyebrow text-accent">Reading it</p><ul className="mt-3 list-disc space-y-2 pl-4"><li>One coral dot inside the band is a normal bad day. Change nothing.</li><li>A dot outside the band is notable: open the report and find out why — the opponent, the surface, a cut that explains it.</li><li>Three matches in a row on the same side of the average, even inside the band, say the level has moved; the trend’s slope says how fast.</li><li>Under FORECAST read the gap, not the dot: <em>+4 vs forecast · forecast was 58%</em> is a match that beat what the last ones predicted; a season of small positive gaps is improvement the average cannot see yet.</li><li>A flat trend with a wide band says the problem is consistency, not level. A steady slope with a narrow band is a real change, in either direction.</li><li>Put the cut on before you judge: 2nd serve points won under Break point, across ten matches, is the honest test of the second serve you have been practising.</li></ul></div></div><figure className="stats-section-figure"><AppScreenshot name="stats" alt="The Stats tab: one metric across a window of matches with its trend" className="mx-auto w-full max-w-[230px]" /><figcaption className="mt-3 text-center text-xs">STATS · a metric, match after match</figcaption></figure></div></section>

        <section id="missing" className="mt-14 scroll-mt-8 rounded-2xl border border-accent/15 bg-accent/[.04] p-6"><h2 className="eyebrow text-accent">Reading a missing value</h2><ul className="mt-4 list-disc space-y-3 pl-4 text-sm"><li>A dash means the value was not captured at this match’s tracking level, or that no points fall under the current cut. It is never a zero.</li><li>A count row — aces, winners, errors — reads a dash, never 0, when none of the selected points was recorded at the level it needs: a score-only set inside a Detailed match has no aces to count, and the Stats tab lists that match as not captured under the cut.</li><li>In a trend, a match with no points under the cut is a gap, not a drop.</li><li>The aggression rows read a dash under ten decided points. The moving average needs two matches; the trend three; the bands five; the forecast five, eight before it may carry a slope.</li><li>Pattern counts come only from recorded landings: Counter and Score matches have no attempts and no completions.</li><li>A row the record cannot hold is not a dash but absent: a rally session lists no break points, a feed-started one no serve rows, a one-serve one no second-serve rows.</li></ul></section>

        <section id="worked" className="mt-14 scroll-mt-8 border-t border-line pt-8"><h2 className="text-2xl font-semibold tracking-tight text-ink">A worked reading</h2><p className="mt-4 text-sm">One Detailed match, lost 4–6 6–3 3–6, read in the order above. The numbers are a demo match; the reasoning is the point.</p><div className="mt-6 grid gap-4 md:grid-cols-2">{[['Cover', 'Best of 3 · sets to 6 · advantage · tiebreak at 6–6. Detailed. 1 h 52. So every second-serve figure is read with advantage games, where a 40–40 point is not the end of it.'], ['Momentum', 'The starred swing sits at 3–3 in the third set: four points, the win chance from 54% to 31%. The comparison shows the share of points barely moved before and after — 48% to 46% — while the win chance fell by a third. The big points were lost, not the rallies. Go to Pressure.'], ['Aggression', 'Margin +9, efficiency 1.3×: the loser built more than they gave. Built 41 · given 32, and of the 32, eleven are invited forced errors. The player dictated and still lost, and a third of what they gave away followed their own short ball.'], ['Points · Serve', 'Points won 51% · break points won 2 of 9. Winners 28 against unforced 19 — the match was played on the loser’s terms. 1st serve in 64%, 1st serve pts won 71%: fine. 2nd serve pts won 38% with 5 double faults: the second serve. Under the Ad track, 2nd serve pts won 29%.'], ['Pressure', 'Pressure points won 41% against Points won 51%: ten points down — the player tightens. Break points saved 7 of 11, break points won 2 of 9: defends the big point, cannot take it. Breaks consolidated 1 of 3: two breaks handed straight back.'], ['Placement · Landings', 'Deep landings 37%, falling from 44% in set 1 to 31% in set 3 under the Set cut. Crosscourt 68%. The eleven invited errors have their reason: short, and always to the same place, and shorter as the match went on.'], ['One number', 'Second serve points won from the ad court under break point — 29% now. The practice: a VS rally with a serve start and Serves · 1, ad court, and a serve session with Wide called from the ad side. Check it on Stats in five matches, not one.']].map(([h, b]) => <div key={h} className="rounded-2xl border border-white/10 p-5"><p className="eyebrow text-accent">{h}</p><p className="mt-3 text-sm">{b}</p></div>)}</div></section>

        <section className="mt-16 border-t border-line pt-8"><p className="eyebrow text-accent">Keep exploring</p><div className="mt-6 grid gap-4 sm:grid-cols-2">{[['stats-and-trends', 'See your progress over time'], ['serve-sessions', 'Serve sessions: a basket at a target']].map(([slug, title]) => <Link href={`/learn/${slug}`} key={slug} className="rounded-2xl border border-line p-6 transition-colors hover:border-accent/30"><p className="text-xs text-muted">Guide</p><h2 className="mt-3 text-lg font-semibold text-ink">{title}</h2><p className="mt-3 text-sm text-accent">Read the guide ↗</p></Link>)}</div></section>
      </article>
    </div>
  </Container>
}
